//! Actual private native services + original signed admission/task ledger.
//! Identity evidence is synthetic; no real provider, user audio or Tauri UI.
use super::{admission::{self,Evidence,Review,Payment,Budget},admission_tests::Fixture,model::*,authority::{Authority,Failure},lease_controller::{Controller,Validity},store::nonce,criteria,recipes};
use super::lease_controller::native_system_sound_task_tests::{Audio,serial};
use crate::chat::Chat;
use std::{sync::Arc,fs};
use serde_json::{json,Value};
pub(in crate::pet_runtime)fn config(audio:&Audio,g:&Record)->crate::pet_config::Configuration{let mut c=audio.config();let policy=c.pets["ai_ollama"].system_access.clone();c.pets.get_mut(&g.spec.owner.pet_id).unwrap().system_access=policy;c}
pub(in crate::pet_runtime)fn save(f:&Fixture,c:&crate::pet_config::Configuration){fs::write(f.path.join("system.json"),serde_json::to_vec(c).unwrap()).unwrap();}
pub(in crate::pet_runtime)fn draft(f:&Fixture,audio:&Audio,provider:&str)->Record{let b=crate::pet_config::blueprints().find(|b|b.routing.chat.as_deref()==Some(provider)||b.routing.task_provider.as_deref()==Some(provider)).unwrap();let g=f.store().create(Spec{received_from:None,restored_from:None,request_id:"original-system-goal".into(),owner:Owner{pet_id:b.id.clone(),provider:provider.into(),adapter:b.runtime.adapter.map(|a|a.key()).unwrap_or(provider).into(),model_hint:None},context:Context::Unbound,intent:"Finite native output plan".into(),criteria:vec!["Native volume35".into(),"Native muted".into()]},100_000).unwrap().record;let(binding,guard)=super::context::prepare(&f.path.join("contexts"),&g,&Chat::persistent(f.path.join("preparation.json")),PreparationMode::Dedicated,"system-context").unwrap();drop(guard);let mut g=f.store().mutate(&g.id,&g.spec.owner.pet_id,&g.revision,"system-context".into(),Action::BindContext{binding},100_001).unwrap().record;let at=crate::assistant_memory::now();g=f.store().mutate(&g.id,&g.spec.owner.pet_id,&g.revision,"system-task".into(),Action::ProposeTask{description:"Exact native output".into()},at).unwrap().record;f.store().mutate(&g.id,&g.spec.owner.pet_id,&g.revision,"system-plan".into(),Action::ProposePlan{task_id:g.tasks[0].id.clone(),steps:vec![audio.proposed(false),audio.proposed(true)]},at).unwrap().record}
pub(in crate::pet_runtime)fn evidence(g:&Record,c:&crate::pet_config::Configuration,now:u64)->Evidence{let b=crate::pet_config::blueprint(&g.spec.owner.pet_id).unwrap();let d=crate::pet_capabilities::Descriptor{schema_version:1,pet_id:b.id.clone(),kind:if b.service{crate::pet_capabilities::Kind::Service}else{crate::pet_capabilities::Kind::Llm},name:"Synthetic native identity".into(),lifecycle:crate::pet_capabilities::Lifecycle::Active,binding:crate::pet_capabilities::Binding{engine_binding:None,provider:Some(g.spec.owner.provider.clone()),adapter:b.runtime.adapter.map(|a|a.key()),model:None,profile:None},revision:"synthetic-owner".into(),observed_at:None,configuration_available:true,capabilities:vec![],concurrency:crate::pet_capabilities::Concurrency{scope:None,max_active:None}};Evidence::observe_system(g,&d,super::native_validity::system_policy_revision(c,g).unwrap(),now).unwrap()}
pub(in crate::pet_runtime)fn criteria()->[criteria::Input;2]{[criteria::Input{criterion_index:0,predicate:criteria::Predicate::SystemSoundVolume{percent:35}},criteria::Input{criterion_index:1,predicate:criteria::Predicate::SystemSoundMute{muted:true}}]}
pub(in crate::pet_runtime)fn review(f:&Fixture,audio:&Audio,g:&Record,c:&crate::pet_config::Configuration)->Review{let now=crate::assistant_memory::now();let path=f.path.join("system.json");let observe=Arc::new(move||serde_json::from_slice(&fs::read(&path).map_err(|_|Error::StorageUnavailable)?).map_err(|_|Error::InvalidInput));Review::prepare_system(g,evidence(g,c,now),Budget{deadline_at:now+60_000,max_model_calls:0,max_tool_calls:2,max_output_bytes:32768,max_tokens:None,max_cost_micros:None,payment:Payment::RuntimeOnly},audio.target(&f.path.join("system.json"),&g.spec.owner.pet_id,false),observe,&criteria(),"system-admission".into(),nonce().unwrap(),now).unwrap()}
fn body(f:&Fixture,g:&Record)->Value{serde_json::from_slice::<Value>(&fs::read(f.path.join("authority").join(format!("{}.json",g.admissions[0].spec.decision_id))).unwrap()).unwrap()["body"].clone()}
#[test]#[ignore="Private native services; synthetic owner metadata, no user audio or provider"]
fn native_system_admission_all_original_owners_use_zero_model_budget_and_one_common_signed_recipe(){
 let _serial=serial();let audio=Audio::new();
 for provider in ["codex","copilot","antigravity","ollama","lmstudio","openai","integration_spotify"]{
  let f=Fixture::new();let a=Authority::ensure(&f.path.join("authority")).unwrap();let g=draft(&f,&audio,provider);let c=config(&audio,&g);save(&f,&c);let r=review(&f,&audio,&g,&c);let p=r.proposal();assert_eq!(p.operation,"goalDeterministic");assert!(p.resolved_model.is_empty()&&p.engine_binding.is_none()&&p.native_peer_plan.is_none());assert_eq!(p.native_system_plan.as_ref().unwrap().steps.len(),2);assert_eq!(p.native_verification.as_ref().unwrap().schema_version,5);
  let now=crate::assistant_memory::now();let approved=r.approve(&g,evidence(&g,&c,now),now).unwrap();let cert=a.certify(&approved,&g,crate::assistant_memory::now()).unwrap();let q=f.store().enqueue_certified(&cert,crate::assistant_memory::now()).unwrap().record;assert_eq!(q.schema_version,62);assert_eq!(q.admissions[0].spec.schema_version,27);assert_eq!(body(&f,&q)["schemaVersion"],48);let old_budget=q.admissions[0].spec.budget.clone();
  let chat=Chat::persistent(f.path.join("main.json"));let now=crate::assistant_memory::now();let pending=Controller::new().unwrap().prepare(&q,&f.path.join("authority"),&f.path.join("contexts"),&chat,&evidence(&q,&c,now),"system-claim".into(),now,Arc::new(|_,_,_|Validity::Current)).unwrap();let now=crate::assistant_memory::now();let (receipt,owned)=pending.claim(&f.store(),&a,&evidence(&q,&c,now),now).unwrap();let g=receipt.record;let o=owned.unwrap();assert_eq!(o.lease().schema_version,2);assert!(o.lease().model.is_empty());let row=&g.admissions[0];
  let attempt=super::effect_budget::Attempt{id:nonce().unwrap(),request_id:"forbidden-model".into(),input_hash:"a".repeat(64),kind:super::effect_budget::Kind::Model,output_reserved:10,phase:super::effect_budget::Phase::Reserved,accepted_output:None,reserved_at:now,started_at:None,finished_at:None};assert_eq!(a.reserve_attempt(&row.spec,row.proof.as_ref().unwrap(),o.lease(),&attempt,now).err(),Some(Failure::Invalid));
  let target=audio.target(&f.path.join("system.json"),&g.spec.owner.pet_id,false);let review=o.review_recipe_with_criteria(&g,&g.plans[0].id,"exact-native-system",target,&c,&[],crate::assistant_memory::now()).unwrap();let(approved,ready)=review.approve(&o,&g,&c,crate::assistant_memory::now()).unwrap();let scope=a.issue_recipe(&row.spec,row.proof.as_ref().unwrap(),o.lease(),&approved,crate::assistant_memory::now()).unwrap();assert_eq!(scope.schema_version,5);assert!(scope.steps.iter().all(|s|s.schema_version==4));ready.activate(&scope).unwrap();let result=o.run_recipe_for_store(&f.store(),&g,&ready,||Ok(c.clone()),|_|{}).unwrap();assert_eq!(result.outcome,recipes::Outcome::GoalCompleted);audio.assert_volume(35.0);let stored=f.store().read(&g.id,&g.spec.owner.pet_id).unwrap();a.verify_completed_goal(&stored).unwrap();assert_eq!(stored.admissions[0].spec.budget,old_budget);assert_eq!(body(&f,&g)["budgetUsage"]["attempts"].as_array().unwrap().len(),2);assert!(body(&f,&g)["budgetUsage"]["attempts"].as_array().unwrap().iter().all(|a|a["kind"]=="tool"));assert!(!f.path.join("main.json").exists());
 }
 println!("NATIVE_SYSTEM_ADMISSION owners=7 absentModels=true originalQueueAuthorityRecipe=true signedCompletion=true modelCalls=0 userAudioWrites=0");
}
#[test]#[ignore="Private native review, no effects or provider"]
fn native_system_admission_exact_review_refuses_changed_grants_arguments_and_incomplete_criteria(){
 let _serial=serial();let audio=Audio::new();let f=Fixture::new();let g=draft(&f,&audio,"ollama");let c=config(&audio,&g);save(&f,&c);let r=review(&f,&audio,&g,&c);let policy=r.proposal().native_system_plan.unwrap();let now=crate::assistant_memory::now();let mut changed=c.clone();changed.pets.get_mut("ai_ollama").unwrap().system_access.as_mut().unwrap().revision="f".repeat(32);save(&f,&changed);assert!(r.confirmation_current(&g,&evidence(&g,&changed,now),now).is_err());save(&f,&c);assert!(r.confirmation_current(&g,&evidence(&g,&c,now),now).is_err());assert!(!f.path.join("authority").exists());
 let r=review(&f,&audio,&g,&c);let now=crate::assistant_memory::now();let approved=r.approve(&g,evidence(&g,&c,now),now).unwrap();let mut changed=g.clone();changed.plans[0].steps[0].operation.as_mut().unwrap().arguments["percent"]=json!(80);assert!(!policy.matches(&changed,approved.spec()));assert!(approved.current(&changed,now).is_err());assert!(criteria::Binding::system_for(&g,&criteria()[..1]).is_err());assert!(approved.current(&g,now).is_err());let fresh=review(&f,&audio,&g,&c);let now=crate::assistant_memory::now();let approved=fresh.approve(&g,evidence(&g,&c,now),now).unwrap();let mut unknown=serde_json::to_value(approved.spec()).unwrap();unknown["nativeSystemPlan"]["output"]["grantRevision"]=json!("0".repeat(32));let forged:admission::AdmissionSpec=serde_json::from_value(unknown).unwrap();let authority=Authority::ensure(&f.path.join("authority")).unwrap();let cert=authority.certify(&approved,&g,now).unwrap();let mut queued=f.store().enqueue_certified(&cert,now).unwrap().record;queued.admissions[0].spec=forged;assert!(authority.verify_queued(&queued,now).is_err());
 println!("NATIVE_SYSTEM_REVIEW observedRevocationSticky=true changedArgumentsRefused=true completeCriteriaRequired=true jsonIsNotAuthority=true noEffects=true");
}
#[test]#[ignore="Private native services and recovery DATA; no user audio or provider"]
fn native_system_admission_reopen_preserves_exact_native_scope_and_cannot_promote_to_peer_or_model(){
 let _serial=serial();let audio=Audio::new();let f=Fixture::new();let a=Authority::ensure(&f.path.join("authority")).unwrap();let g=draft(&f,&audio,"ollama");let c=config(&audio,&g);save(&f,&c);let r=review(&f,&audio,&g,&c);let now=crate::assistant_memory::now();let approved=r.approve(&g,evidence(&g,&c,now),now).unwrap();let cert=a.certify(&approved,&g,now).unwrap();let q=f.store().enqueue_certified(&cert,now).unwrap().record;let store=super::store::Store::existing_verified(&f.path.join("goals"),&f.path.join("authority")).unwrap().unwrap();let reopened=store.read(&q.id,&q.spec.owner.pet_id).unwrap();assert_eq!(super::model::fingerprint(&reopened).unwrap(),super::model::fingerprint(&q).unwrap());let spec=&q.admissions[0].spec;
 for version in [2,4,5,26]{let mut bad=spec.clone();bad.schema_version=version;assert!(!bad.binding_format());}let mut bad=spec.clone();bad.resolved_model="unexpected".into();assert!(!bad.binding_format());let mut bad=spec.clone();bad.native_system_plan=None;assert!(!bad.binding_format());let mut bad=spec.clone();bad.budget.max_model_calls=1;assert!(!bad.binding_format());let mut bad=spec.clone();bad.native_verification.as_mut().unwrap().conditions.pop();assert!(!bad.binding_format());
 a.revoke(spec,q.admissions[0].proof.as_ref().unwrap(),now).unwrap();let before=fs::read(f.path.join("authority").join(format!("{}.json",spec.decision_id))).unwrap();let chat=Chat::persistent(f.path.join("main.json"));assert!(Controller::new().unwrap().prepare(&q,&f.path.join("authority"),&f.path.join("contexts"),&chat,&evidence(&q,&c,now),"cannot-replay".into(),now,Arc::new(|_,_,_|Validity::Current)).is_err());assert_eq!(fs::read(f.path.join("authority").join(format!("{}.json",spec.decision_id))).unwrap(),before);
 println!("NATIVE_SYSTEM_REOPEN exactAdmissionBudgetTargetPreserved=true revokedCannotClaim=true peerModelPromotionRefused=true noEffects=true");
}

#[test]#[ignore="Private native services, existing Stop/drain; no user audio or provider"]
fn native_system_admission_stop_prevents_first_effect_and_closes_original_authority_without_new_budget(){
 let _serial=serial();let audio=Audio::new();let f=Fixture::new();let a=Authority::ensure(&f.path.join("authority")).unwrap();let g=draft(&f,&audio,"ollama");let c=config(&audio,&g);save(&f,&c);let review=review(&f,&audio,&g,&c);let now=crate::assistant_memory::now();let approved=review.approve(&g,evidence(&g,&c,now),now).unwrap();let cert=a.certify(&approved,&g,crate::assistant_memory::now()).unwrap();let q=f.store().enqueue_certified(&cert,crate::assistant_memory::now()).unwrap().record;
 let chat=Chat::persistent(f.path.join("main.json"));let now=crate::assistant_memory::now();let pending=Controller::new().unwrap().prepare(&q,&f.path.join("authority"),&f.path.join("contexts"),&chat,&evidence(&q,&c,now),"stop-system-claim".into(),now,Arc::new(|_,_,_|Validity::Current)).unwrap();let now=crate::assistant_memory::now();let(receipt,owned)=pending.claim(&f.store(),&a,&evidence(&q,&c,now),now).unwrap();let g=receipt.record;let o=owned.unwrap();let step=&g.plans[0].steps[0];let review=o.review_step(&g,&g.plans[0].id,&step.id,audio.target(&f.path.join("system.json"),"ai_ollama",false),&c,crate::assistant_memory::now()).unwrap();let(approved,ready)=review.approve(&o,&g,&c,crate::assistant_memory::now()).unwrap();let row=&g.admissions[0];a.issue_step(&row.spec,row.proof.as_ref().unwrap(),o.lease(),&approved,crate::assistant_memory::now()).unwrap();
 let stopped=super::authority_store::mutate_with_authority(&f.store(),&f.path.join("authority"),&g.id,&g.spec.owner.pet_id,&g.revision,"cancel-system-before-effect".into(),Action::Cancel,crate::assistant_memory::now()).unwrap().record;assert_eq!(stopped.state,State::Stopping);assert!(o.run_step(&stopped,&ready,&c).is_err());assert_eq!(o.workers(),0);assert!(body(&f,&g).get("budgetUsage").is_none());let drained=o.drain(super::leases::DrainOutcome::Confirmed).unwrap();let closed=f.store().drain_owned(&a,&drained,crate::assistant_memory::now()).unwrap().record;assert_eq!(closed.state,State::Cancelled);assert_eq!(body(&f,&g)["schemaVersion"],48);assert_eq!(body(&f,&g)["phase"],"revoked");assert_eq!(closed.admissions[0].spec.budget,q.admissions[0].spec.budget);a.verify_goal_origin(&closed).unwrap();
 println!("NATIVE_SYSTEM_STOP beforeEffectBlocked=true zeroBudget=true originalOwnerDrained=true cancelledPreserved=true noEffects=true");
}
